INSERT INTO sales_daily (generation,day,currency,orders,cancelled,gross,refunds,net) SELECT generation,day,currency,countIf(status NOT IN ('cancelled','delivery_failed')),countIf(status IN ('cancelled','delivery_failed')),sumIf(total,status NOT IN ('cancelled','delivery_failed')),sum(refunded),sumIf(total,status NOT IN ('cancelled','delivery_failed'))-sum(refunded) FROM reporting_order_facts WHERE generation='{generation}' GROUP BY generation,day,currency;
INSERT INTO product_performance_daily (generation,day,product_id,sku,name,currency,units,revenue) SELECT i.generation,i.day,i.product_id,any(i.sku),any(i.name),i.currency,sum(i.quantity),sum(i.net) FROM reporting_order_items i INNER JOIN reporting_order_facts o ON i.generation=o.generation AND i.order_id=o.order_id WHERE i.generation='{generation}' AND o.status NOT IN ('cancelled','delivery_failed') AND o.refunded=0 GROUP BY i.generation,i.day,i.product_id,i.currency;
INSERT INTO customer_ltv (generation,customer_id,currency,first_order,last_order,orders,value) SELECT generation,customer_id,currency,min(day),max(day),count(),sum(total-refunded) FROM reporting_order_facts WHERE generation='{generation}' AND status NOT IN ('cancelled','delivery_failed') GROUP BY generation,customer_id,currency;
INSERT INTO funnel_daily (generation,day,visitors,carts,checkouts,purchases) SELECT '{generation}',day,countIf(viewed>0),countIf(viewed>0 AND cart>=viewed),countIf(viewed>0 AND cart>=viewed AND checkout>=cart),countIf(viewed>0 AND cart>=viewed AND checkout>=cart AND purchase>=checkout) FROM (SELECT toDate(occurred_at) day,session_id,minIf(toUnixTimestamp64Milli(occurred_at),event_type='page_view') viewed,minIf(toUnixTimestamp64Milli(occurred_at),event_type='cart_added') cart,minIf(toUnixTimestamp64Milli(occurred_at),event_type='checkout_started') checkout,minIf(toUnixTimestamp64Milli(occurred_at),event_type='order_placed') purchase FROM browser_events FINAL WHERE occurred_at<parseDateTime64BestEffort('{started_at}') GROUP BY day,session_id) GROUP BY day;
INSERT INTO traffic_daily (generation,day,source,sessions) SELECT '{generation}',day,source,count() FROM (SELECT toDate(occurred_at) day,session_id,argMin(source,occurred_at) source FROM browser_events FINAL WHERE event_type='page_view' AND occurred_at<parseDateTime64BestEffort('{started_at}') GROUP BY day,session_id) GROUP BY day,source;
INSERT INTO retention_cohorts (generation,cohort,month,customers,returning) SELECT '{generation}',c.cohort,toUInt32(dateDiff('month',c.cohort,toStartOfMonth(o.day))) month,any(c.customers),uniqExact(o.customer_id) FROM (SELECT customer_id,toStartOfMonth(min(first_order)) cohort,count() OVER (PARTITION BY toStartOfMonth(min(first_order))) customers FROM customer_ltv WHERE generation='{generation}' GROUP BY customer_id) c INNER JOIN reporting_order_facts o ON c.customer_id=o.customer_id WHERE o.generation='{generation}' AND o.status NOT IN ('cancelled','delivery_failed') AND o.refunded=0 AND dateDiff('month',c.cohort,toStartOfMonth(o.day)) BETWEEN 0 AND 11 GROUP BY c.cohort,month
